/* =====================================================================
   MRA IPD Audit — ข้อมูลตั้งต้น (seed)
   เกณฑ์ตามคู่มือ Medical Record Audit Guideline ปี 2563 (IPD) — 12 content, 106 เกณฑ์
   รันหลัง mra_ipd_schema.sql
   ===================================================================== */
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;


VALUES ('MRA-IPD-2563', N'Medical Record Audit Guideline 2563 (IPD)', '2020-01-01');
DECLARE @Set INT = SCOPE_IDENTITY();
DECLARE @C INT;


/* ---- Content 1: Discharge summary: Dx., OP ---- */
VALUES (@Set, 1, 'DC_DX', N'Discharge summary: Dx., OP', N'สรุปการวินิจฉัยโรค และการผ่าตัด/หัตถการ', 0, 0, 0, NULL);
SET @C = SCOPE_IDENTITY();

/* ---- Content 2: Discharge summary: Other ---- */
VALUES (@Set, 2, 'DC_OTHER', N'Discharge summary: Other', N'เนื้อหาอื่นๆ ของใบสรุปการจำหน่ายและส่วนประกอบอื่นๆ', 0, 0, 0, NULL);
SET @C = SCOPE_IDENTITY();

/* ---- Content 3: Informed consent ---- */
VALUES (@Set, 3, 'CONSENT', N'Informed consent', N'บันทึกการรับทราบข้อมูลและยินยอมรับการรักษา หรือทำหัตถการ', 0, 0, 0, NULL);
SET @C = SCOPE_IDENTITY();

/* ---- Content 4: History ---- */
VALUES (@Set, 4, 'HISTORY', N'History', N'บันทึกการซักประวัติโดยแพทย์', 0, 0, 0, NULL);
SET @C = SCOPE_IDENTITY();

/* ---- Content 5: Physical exam ---- */
VALUES (@Set, 5, 'PHYSICAL', N'Physical exam', N'บันทึกการตรวจร่างกายโดยแพทย์', 0, 0, 0, NULL);
SET @C = SCOPE_IDENTITY();

/* ---- Content 6: Progress note ---- */
VALUES (@Set, 6, 'PROGRESS', N'Progress note', N'บันทึกความก้าวหน้าการดำเนินโรค และคำสั่งการรักษาของแพทย์ (Doctor''s order)', 0, 0, 0, NULL);
SET @C = SCOPE_IDENTITY();

/* ---- Content 7: Consultation record ---- */
VALUES (@Set, 7, 'CONSULT', N'Consultation record', N'บันทึกการปรึกษาโรคระหว่างแผนกหรือกลุ่มงานของแพทย์', 1, 0, 0, NULL);
SET @C = SCOPE_IDENTITY();
VALUES (@C, 4, 1, 4, N'ไม่มีลายมือชื่อแพทย์ผู้ขอปรึกษา (ข้อ 4) จึงไม่ได้คะแนนข้อ 1-4');
VALUES (@C, 8, 5, 8, N'ไม่มีลายมือชื่อแพทย์ผู้ให้คำปรึกษา (ข้อ 8) จึงไม่ได้คะแนนข้อ 5-8');

/* ---- Content 8: Anesthetic record ---- */
VALUES (@Set, 8, 'ANESTHETIC', N'Anesthetic record', N'บันทึกทางวิสัญญีวิทยา', 1, 0, 0, NULL);
SET @C = SCOPE_IDENTITY();

/* ---- Content 9: Operative note ---- */
VALUES (@Set, 9, 'OPERATIVE', N'Operative note', N'บันทึกการทำผ่าตัด หรือทำหัตถการ', 1, 0, 0, NULL);
SET @C = SCOPE_IDENTITY();

/* ---- Content 10: Labour record ---- */
VALUES (@Set, 10, 'LABOUR', N'Labour record', N'บันทึกการติดตามเฝ้าระวังก่อนคลอด ระหว่างคลอด และหลังคลอด', 1, 0, 0, N'ประเมินเฉพาะกรณีที่มีการคลอดในโรงพยาบาล (รวมการผ่าตัดคลอด)');
SET @C = SCOPE_IDENTITY();

/* ---- Content 11: Rehabilitation record ---- */
VALUES (@Set, 11, 'REHAB', N'Rehabilitation record', N'บันทึกการให้การฟื้นฟูสมรรถภาพ หรือการทำกายภาพบำบัด', 1, 0, 0, NULL);
SET @C = SCOPE_IDENTITY();

/* ---- Content 12: Nurses' note ---- */
VALUES (@Set, 12, 'NURSE', N'Nurses'' note', N'บันทึกการพยาบาล', 0, 1, 1, NULL);
SET @C = SCOPE_IDENTITY();

/* ตรวจจำนวน: ต้องได้ 12 content, 106 เกณฑ์ (เลือก NA ได้ 10 เกณฑ์) */
DECLARE @nContent INT = (SELECT COUNT(*) FROM mra.AuditContent WHERE CriteriaSetId = @Set);
DECLARE @nCriteria INT = (SELECT COUNT(*) FROM mra.AuditCriterion c
                          JOIN mra.AuditContent a ON a.ContentId = c.ContentId
                          WHERE a.CriteriaSetId = @Set);
IF @nContent <> 12 OR @nCriteria <> 106
   THROW 50001, N'จำนวนเกณฑ์ไม่ครบ', 1;

COMMIT TRANSACTION;

