INSERT INTO mra.SystemSetting (SettingKey, SettingValue, Description) VALUES
 ('HCODE',          N'',                     N'รหัสสถานพยาบาล 5 หลัก (กรอกให้ถูกต้อง)'),
 ('HOSPITAL_NAME',  N'โรงพยาบาลสระบุรี',      N'ชื่อสถานพยาบาลบนแบบฟอร์มและใบสรุป'),
 ('MIN_FULL_SCORE', N'56',                   N'คะแนนเต็มขั้นต่ำที่ถือว่าเวชระเบียนมีข้อมูลพอให้ประเมิน');
INSERT INTO mra.CriteriaSet (SetCode, SetName, EffectiveFrom)
INSERT INTO mra.AuditContent (CriteriaSetId, ContentNo, ContentCode, TitleEn, TitleTh, AllowContentNA, AllowDeduction, MaxDeduction, HintText)
INSERT INTO mra.AuditCriterion (ContentId, CriterionNo, CriterionText, AllowNA, NoteText) VALUES
 (@C, 1, N'สรุปการวินิจฉัยโรคหลัก (principal diagnosis) เป็นคำวินิจฉัยโรค (clinical term) ไม่ใช่รหัส ICD-10 สอดคล้องกับข้อมูลในเวชระเบียน และมีเพียงโรคเดียว', 0, NULL),
 (@C, 2, N'สรุปการวินิจฉัยโรคร่วม (comorbidity) โรคแทรก (complication) เป็นคำวินิจฉัยโรค สอดคล้องกับข้อมูล และสรุปสาเหตุการบาดเจ็บ/พิษจากสารเคมี (ถ้ามี)', 1, N'กรณีไม่มีโรคร่วม โรคแทรก และสาเหตุการบาดเจ็บ ให้ระบุ NA'),
 (@C, 3, N'สรุปการทำหัตถการและ/หรือการผ่าตัด ถูกต้องและครบถ้วนตรงกับข้อมูลในเวชระเบียน', 1, N'กรณีไม่มีการทำหัตถการหรือผ่าตัด ให้ระบุ NA'),
 (@C, 4, N'บันทึกวันเดือนปีและเวลาที่เริ่มต้นและสิ้นสุดของการทำหัตถการในห้องผ่าตัด (operating room) ทุกครั้ง', 1, N'กรณีไม่มีการทำหัตถการหรือผ่าตัด ให้ระบุ NA'),
 (@C, 5, N'ไม่ใช้ตัวย่อในการสรุปโรคหลัก โรคร่วม โรคแทรก สาเหตุภายนอก การทำหัตถการ/ผ่าตัด และสรุปด้วยลายมือที่สามารถอ่านออกได้', 0, NULL),
 (@C, 6, N'สรุปข้อมูลใน clinical summary ครบทุกข้อ: สาเหตุ/ปัญหาแรกรับหรือวินิจฉัยเมื่อสิ้นสุดการรักษา, การส่งตรวจที่สำคัญ, การรักษาและผลการรักษาที่จำเป็น, แผนฟื้นฟู/เสริมสุขภาพหลังจำหน่าย (ถ้ามี), Home medication', 0, NULL),
 (@C, 7, N'สรุปสาเหตุการตายให้สอดคล้องกับข้อมูลในเวชระเบียน', 1, N'กรณีผู้ป่วยไม่เสียชีวิต ให้ระบุ NA'),
 (@C, 8, N'สรุป discharge status และ discharge type ถูกต้องตรงกับข้อมูลในเวชระเบียน กรณี discharge type เป็น "by transfer" ต้องระบุชื่อสถานพยาบาลที่ส่งต่อ', 0, NULL),
 (@C, 9, N'มีการลงลายมือชื่อแพทย์ผู้รับผิดชอบในการรักษา หรือแพทย์ผู้สรุป ระบุชื่อ นามสกุล และเลขที่ใบประกอบวิชาชีพเวชกรรม', 0, NULL);
INSERT INTO mra.AuditContent (CriteriaSetId, ContentNo, ContentCode, TitleEn, TitleTh, AllowContentNA, AllowDeduction, MaxDeduction, HintText)
INSERT INTO mra.AuditCriterion (ContentId, CriterionNo, CriterionText, AllowNA, NoteText) VALUES
 (@C, 1, N'มีข้อมูลชื่อ นามสกุล เพศ (หรือคำนำหน้าชื่อ) และอายุ (หรือวัน เดือน ปีเกิด) ของผู้ป่วยครบถ้วน (ไม่ทราบวันเดือนเกิด อนุโลมปี พ.ศ. ได้; ไม่ทราบว่าเป็นใคร ให้ระบุ "ชายหรือหญิงไม่ทราบชื่อ")', 0, NULL),
 (@C, 2, N'มีข้อมูลเลขประจำตัวประชาชนของผู้ป่วย หรือเลขที่ใบต่างด้าว (ไม่สามารถขึ้นทะเบียนเป็นคนไทยได้ ระบุ "ไม่มีเลขที่บัตร"; ไม่รู้สึกตัวระบุ "ไม่รู้สึกตัว"; เสียชีวิตและไม่พบหลักฐาน ระบุ "เสียชีวิตและไม่พบหลักฐาน")', 0, NULL),
 (@C, 3, N'มีข้อมูลที่อยู่ปัจจุบันของผู้ป่วย (ไม่รู้สึกตัวระบุ "ไม่รู้สึกตัว"; เสียชีวิตไม่พบหลักฐานระบุ "เสียชีวิตและไม่พบหลักฐาน"; ซักประวัติไม่ได้ระบุ "ซักประวัติไม่ได้")', 0, NULL),
 (@C, 4, N'มีข้อมูลชื่อโรงพยาบาล HN และ AN ถูกต้องตรงกับข้อมูลที่ปรากฏทุกแห่งในเวชระเบียน', 0, NULL),
 (@C, 5, N'มีข้อมูลวัน เดือน ปี และเวลาที่ admit และวัน เดือน ปี และเวลาที่ discharge ถูกต้องตรงกับข้อมูลในเวชระเบียน', 0, NULL),
 (@C, 6, N'มีข้อมูลจำนวนวันที่อยู่โรงพยาบาล (LOS) และจำนวนวันที่ลากลับบ้านระหว่างอยู่โรงพยาบาล (total leave days) ถูกต้องตรงกับข้อมูลในเวชระเบียน', 0, NULL),
 (@C, 7, N'มีข้อมูลชื่อ นามสกุล ผู้ให้รหัสโรค และข้อมูลชื่อ นามสกุล ผู้ให้รหัสหัตถการ', 0, NULL);
INSERT INTO mra.AuditContent (CriteriaSetId, ContentNo, ContentCode, TitleEn, TitleTh, AllowContentNA, AllowDeduction, MaxDeduction, HintText)
INSERT INTO mra.AuditCriterion (ContentId, CriterionNo, CriterionText, AllowNA, NoteText) VALUES
 (@C, 1, N'มีการบันทึกชื่อและนามสกุลผู้ป่วยถูกต้องชัดเจน', 0, NULL),
 (@C, 2, N'มีลายมือชื่อผู้ให้คำอธิบาย (ระบุชื่อ นามสกุล และตำแหน่ง) เกี่ยวกับการรักษาพยาบาล ก่อนลงลายมือชื่อยินยอมรับการรักษาหรือปฏิเสธการรักษา', 0, NULL),
 (@C, 3, N'มีลายมือชื่อหรือลายพิมพ์นิ้วมือของผู้รับทราบข้อมูลและยินยอมให้ทำการรักษาหรือหัตถการ (ระบุชื่อ นามสกุล) กรณีอายุน้อยกว่า 18 ปีหรือสติสัมปชัญญะไม่สมบูรณ์ ให้ผู้ปกครอง/ผู้ดูแลลงนามแทน ระบุชื่อ นามสกุล และความสัมพันธ์ ยกเว้นกรณีฉุกเฉินหรือผู้ป่วยอายุน้อยกว่า 18 ปีมาคนเดียวและยินยอมด้วยตนเองได้', 0, NULL),
 (@C, 4, N'มีลายมือชื่อหรือลายพิมพ์นิ้วมือของพยานฝ่ายผู้ป่วย 1 คน (ระบุชื่อ นามสกุล และความสัมพันธ์กับผู้ป่วย กรณีมาคนเดียวให้ระบุ "มาคนเดียว")', 0, NULL),
 (@C, 5, N'มีลายมือชื่อพยานฝ่ายเจ้าหน้าที่โรงพยาบาล 1 คน (ระบุชื่อ นามสกุล และตำแหน่ง โดยต้องไม่เป็นบุคคลเดียวกันกับผู้ให้คำอธิบาย)', 0, NULL),
 (@C, 6, N'มีข้อมูลรายละเอียดเหตุผล หรือความจำเป็นในการเข้ารับการรักษา วิธีการรักษาหรือหัตถการ การใช้ยาระงับความรู้สึก ที่สอดคล้องกับสภาพปัญหาของผู้ป่วย ที่แจ้งแก่ผู้ป่วยและญาติรับทราบ', 0, NULL),
 (@C, 7, N'มีข้อมูลรายละเอียดเกี่ยวกับทางเลือก ข้อดี ข้อเสียของทางเลือกในการรักษาที่แจ้งแก่ผู้ป่วยและญาติรับทราบ (สอดคล้องกับเกณฑ์ข้อที่ 6)', 0, NULL),
 (@C, 8, N'มีข้อมูลรายละเอียดเกี่ยวกับระยะเวลาในการรักษา ผลการรักษา ความเสี่ยง และภาวะแทรกซ้อนที่อาจเกิดขึ้น (สอดคล้องกับเกณฑ์ข้อที่ 6)', 0, NULL),
 (@C, 9, N'มีการบันทึกระบุวัน เดือน ปี และเวลา ที่รับทราบและยินยอมให้ทำการรักษา', 0, NULL);
INSERT INTO mra.AuditContent (CriteriaSetId, ContentNo, ContentCode, TitleEn, TitleTh, AllowContentNA, AllowDeduction, MaxDeduction, HintText)
INSERT INTO mra.AuditCriterion (ContentId, CriterionNo, CriterionText, AllowNA, NoteText) VALUES
 (@C, 1, N'บันทึก chief complaint: อาการและระยะเวลา หรือปัญหาที่ผู้ป่วยต้องมาโรงพยาบาล', 0, NULL),
 (@C, 2, N'บันทึก present illness ในส่วน 5W2H (what, where, when, why, who, how, how many) อย่างน้อย 3 ข้อ (ไม่รู้สึกตัวหรือซักประวัติไม่ได้ ต้องบันทึกว่า "ไม่รู้สึกตัว" หรือ "ซักประวัติไม่ได้")', 0, NULL),
 (@C, 3, N'บันทึก present illness ในส่วนการรักษาที่ได้มาแล้ว หรือประวัติการรักษาที่ผ่านมา (รวมการรับประทานยาเองจากบ้าน การดูแลตนเองก่อนมาโรงพยาบาล) (ไม่ได้รักษาที่ไหนมาก่อน ต้องระบุ "ไม่ได้รักษาจากที่ใด")', 0, NULL),
 (@C, 4, N'บันทึก past illness ที่สำคัญและเกี่ยวข้องกับปัญหาที่มา หรือสอดคล้องกับปัญหาที่สงสัย (ไม่มี past illness ต้องระบุว่าไม่มี)', 0, NULL),
 (@C, 5, N'บันทึกประวัติการแพ้ยาและประวัติการแพ้อื่นๆ พร้อมระบุชื่อยาและสิ่งที่แพ้ (ไม่ทราบต้องระบุ "ไม่ทราบ"; ไม่มีต้องระบุ "ไม่มีประวัติการแพ้ยาและการแพ้อื่นๆ" หรือข้อความที่แสดงว่าได้ซักประวัติแล้ว)', 0, NULL),
 (@C, 6, N'บันทึกประวัติอื่นๆ ได้แก่ Family history หรือ personal history หรือประวัติการทำงานที่เกี่ยวข้องกับปัญหาครั้งนี้ (หญิงอายุ 11-60 ปี ต้องบันทึกประวัติประจำเดือน; เด็ก 0-14 ปี ต้องบันทึกประวัติ vaccination และ growth development)', 0, NULL),
 (@C, 7, N'บันทึกการซักประวัติการเจ็บป่วยของระบบร่างกายอื่นๆ (review of system) ทุกระบบ', 0, NULL),
 (@C, 8, N'มีการบันทึกด้วยลายมือชื่อแพทย์ โดยสามารถระบุได้ว่าเป็นผู้ใด จากชื่อ นามสกุล และเลขที่ใบอนุญาตประกอบวิชาชีพเวชกรรม', 1, N'ประเมินในกรณีที่แยกใบกับ physical examination (ใบเดียวกันให้ระบุ NA)'),
 (@C, 9, N'ระบุแหล่งที่มาของข้อมูล เช่น ประวัติได้จากตัวผู้ป่วยเองหรือญาติ หรือประวัติเก่าจากเอกสารในเวชระเบียนหรือเอกสารใบส่งต่อ', 0, NULL);
INSERT INTO mra.AuditContent (CriteriaSetId, ContentNo, ContentCode, TitleEn, TitleTh, AllowContentNA, AllowDeduction, MaxDeduction, HintText)
INSERT INTO mra.AuditCriterion (ContentId, CriterionNo, CriterionText, AllowNA, NoteText) VALUES
 (@C, 1, N'มีการบันทึก vital signs: temperature, pulse rate, respiration rate และ blood pressure (blood pressure ยกเว้นในเด็กอายุน้อยกว่า 5 ปี โดยพิจารณาตามสภาพปัญหาของผู้ป่วย)', 0, NULL),
 (@C, 2, N'มีบันทึกน้ำหนักทุกราย และส่วนสูง (เด็กบันทึกทุกราย; ผู้ใหญ่เมื่อจำเป็นต้องใช้ BMI หรือ BSA ในการวางแผนการรักษา เช่น ยาเคมีบำบัด)', 0, N'กรณีชั่งน้ำหนักและวัดส่วนสูงไม่ได้ ต้องระบุเหตุผลที่เหมาะสม'),
 (@C, 3, N'มีการบันทึกการตรวจร่างกายจากการ ดู คลำ เคาะ ฟัง ที่นำไปสู่การวินิจฉัยที่สอดคล้องกับ chief complaint ซึ่งมิใช่เขียนแค่คำว่า "ปกติ" หรือ "WNL"', 0, NULL),
 (@C, 4, N'มีการบันทึกโดยการวาดรูปหรือแสดงกราฟิก สิ่งที่ตรวจพบความผิดปกติที่ถูกต้อง', 1, N'ตรวจไม่พบความผิดปกติ หรือแสดงกราฟิกไม่ได้ ให้ระบุ NA โดยต้องได้คะแนนในเกณฑ์ข้อ 3'),
 (@C, 5, N'มีการบันทึกการตรวจร่างกายทุกระบบ ซึ่งมิใช่เขียนแค่คำว่า "ปกติ" หรือ "ทุกระบบ WNL"', 0, NULL),
 (@C, 6, N'มีการสรุปปัญหาของผู้ป่วยที่เข้ารับการรักษาในครั้งนี้ (problem list)', 0, NULL),
 (@C, 7, N'มีการสรุปวินิจฉัยขั้นต้น (provisional diagnosis) ที่สอดคล้องกับประวัติ และ/หรือผลการตรวจร่างกาย', 0, NULL),
 (@C, 8, N'มีบันทึกรายละเอียดแผนการรักษาในการ admit ครั้งนี้', 0, N'บันทึกว่า "admit" เฉยๆ ถือว่าไม่ผ่าน'),
 (@C, 9, N'มีการบันทึกลายมือชื่อแพทย์ที่รับผิดชอบในการตรวจร่างกาย โดยสามารถระบุได้ว่าเป็นผู้ใด จากชื่อ นามสกุล และเลขที่ใบอนุญาตประกอบวิชาชีพเวชกรรม', 1, N'ประเมินในกรณีที่แยกใบกับ history (ใบเดียวกันให้ระบุ NA)');
INSERT INTO mra.AuditContent (CriteriaSetId, ContentNo, ContentCode, TitleEn, TitleTh, AllowContentNA, AllowDeduction, MaxDeduction, HintText)
INSERT INTO mra.AuditCriterion (ContentId, CriterionNo, CriterionText, AllowNA, NoteText) VALUES
 (@C, 1, N'มีการลงวันเดือนปี และเวลา ทุกครั้งที่บันทึก progress note', 0, NULL),
 (@C, 2, N'มีการบันทึกทุกวันใน 3 วันแรก', 0, NULL),
 (@C, 3, N'มีการบันทึกเนื้อหาครอบคลุม SOAP (subjective, objective, assessment, plan) ใน 3 วันแรก', 0, NULL),
 (@C, 4, N'มีการบันทึกทุกครั้งที่มีการเปลี่ยนแปลงอาการ หรือการรักษา หรือให้ยา หรือมีการทำ invasive procedure หรือเปลี่ยนแปลงแพทย์ผู้ดูแล', 0, NULL),
 (@C, 5, N'บันทึกเนื้อหาครอบคลุม SOAP ทุกครั้งที่มีการเปลี่ยนแปลงอาการ หรือการรักษา หรือให้ยา หรือมีการทำ invasive procedure หรือเปลี่ยนแปลงแพทย์ผู้ดูแล', 0, NULL),
 (@C, 6, N'มีการบันทึกการแปลผล investigation ที่สำคัญ และมีการวินิจฉัยร่วมกับการวางแผนการรักษาเมื่อผล investigation ผิดปกติ', 0, NULL),
 (@C, 7, N'มีการบันทึก progress note ลงตรงตำแหน่งที่หน่วยบริการกำหนดให้บันทึก', 0, NULL),
 (@C, 8, N'มีการบันทึกด้วยลายมือที่อ่านออกได้ และลงลายมือชื่อแพทย์ที่รับผิดชอบในการบันทึก โดยสามารถระบุได้ว่าเป็นผู้ใด', 0, NULL),
 (@C, 9, N'การลงวันเดือนปีและเวลา พร้อมลงนามกำกับในใบคำสั่งการรักษา (ทั้ง order for one day และ continue) ทุกครั้งที่มีการสั่งการรักษา โดยสามารถระบุได้ว่าเป็นผู้ใด', 0, NULL);
INSERT INTO mra.AuditContent (CriteriaSetId, ContentNo, ContentCode, TitleEn, TitleTh, AllowContentNA, AllowDeduction, MaxDeduction, HintText)
INSERT INTO mra.AuditCriterion (ContentId, CriterionNo, CriterionText, AllowNA, NoteText) VALUES
 (@C, 1, N'มีบันทึกวันเดือนปี เวลา ความจำเป็นเร่งด่วน และหน่วยงานที่ขอปรึกษา', 0, NULL),
 (@C, 2, N'มีการบันทึกขอปรึกษา โดยระบุปัญหาที่ต้องการปรึกษาที่ชัดเจน', 0, NULL),
 (@C, 3, N'มีบันทึกประวัติการตรวจร่างกายและการรักษาโดยย่อของแพทย์ผู้ขอปรึกษา', 0, NULL),
 (@C, 4, N'มีการบันทึกด้วยลายมือที่อ่านออกได้และลงลายมือชื่อแพทย์ผู้ขอปรึกษา โดยสามารถระบุได้ว่าเป็นผู้ใด จากชื่อ นามสกุล และเลขที่ใบอนุญาตประกอบวิชาชีพเวชกรรม', 0, N'ไม่ผ่านข้อนี้ จะไม่ได้คะแนนข้อ 1-4 (คำนวณให้อัตโนมัติ)'),
 (@C, 5, N'มีบันทึกผลการตรวจประเมินเพิ่มเติมและคำวินิจฉัยของผู้รับปรึกษา', 0, NULL),
 (@C, 6, N'มีบันทึกความเห็น หรือแผนการรักษา หรือการให้คำแนะนำ', 0, NULL),
 (@C, 7, N'มีบันทึกวัน เดือน ปี และเวลา ที่ผู้รับปรึกษามาตรวจผู้ป่วย', 0, NULL),
 (@C, 8, N'มีการบันทึกด้วยลายมือที่อ่านออกได้ และลงลายมือชื่อแพทย์ผู้ให้คำปรึกษา โดยสามารถระบุได้ว่าเป็นผู้ใด จากชื่อ นามสกุล และเลขที่ใบอนุญาตประกอบวิชาชีพเวชกรรม', 0, N'ไม่ผ่านข้อนี้ จะไม่ได้คะแนนข้อ 5-8 (คำนวณให้อัตโนมัติ)'),
 (@C, 9, N'แพทย์ผู้ให้คำปรึกษา บันทึกผลการให้คำปรึกษาลงตรงตำแหน่งที่หน่วยบริการกำหนด', 0, NULL);
INSERT INTO mra.CriterionGate (ContentId, SignatureCriterionNo, CoverFromNo, CoverToNo, Description)
INSERT INTO mra.CriterionGate (ContentId, SignatureCriterionNo, CoverFromNo, CoverToNo, Description)
INSERT INTO mra.AuditContent (CriteriaSetId, ContentNo, ContentCode, TitleEn, TitleTh, AllowContentNA, AllowDeduction, MaxDeduction, HintText)
INSERT INTO mra.AuditCriterion (ContentId, CriterionNo, CriterionText, AllowNA, NoteText) VALUES
 (@C, 1, N'มีการบันทึก status ผู้ป่วยก่อนให้ยาระงับความรู้สึกและวิธีให้ยาระงับความรู้สึก', 0, NULL),
 (@C, 2, N'มีบันทึกโรคก่อนผ่าตัด ซึ่งต้องสอดคล้องกับการวินิจฉัยของแพทย์', 0, N'ข้อมูลขัดแย้งกัน ถือว่าไม่ผ่าน'),
 (@C, 3, N'มีบันทึกชนิดและชื่อการผ่าตัด ซึ่งต้องสอดคล้องกับการผ่าตัดของแพทย์', 0, N'ข้อมูลขัดแย้งกัน ถือว่าไม่ผ่าน'),
 (@C, 4, N'มีบันทึกก่อนการผ่าตัด (pre anesthetic evaluation) โดยทีมวิสัญญี มีการระบุประวัติการได้รับยาระงับความรู้สึกก่อนหน้า (ถ้ามี)', 1, N'ยกเว้นผู้ป่วย admit วันเดียวกับวันผ่าตัด หรือกรณีฉุกเฉิน (ระบุ NA)'),
 (@C, 5, N'มีบันทึกสัญญาณชีพและบันทึกการติดตามเฝ้าระวัง ระหว่างให้ยาอย่างน้อยทุก 5 นาที', 0, NULL),
 (@C, 6, N'มีบันทึก intake, output, blood loss, total intake และ total output', 0, NULL),
 (@C, 7, N'มีบันทึกการดูแลผู้ป่วยหลังสิ้นสุดการผ่าตัด 1 ชั่วโมง (recovery room) ตามมาตรฐานราชวิทยาลัยวิสัญญีแพทย์ โดยทีมวิสัญญี', 1, N'ผู้ป่วย on endotracheal tube และส่งต่อเข้าตึกผู้ป่วย ให้ระบุ NA'),
 (@C, 8, N'มีบันทึกการดูแลผู้ป่วยหลังการผ่าตัด (post anesthetic round) โดยทีมวิสัญญี และต้องระบุปัญหาจากการได้รับยาระงับความรู้สึกในครั้งนี้', 0, N'หากไม่มีต้องระบุ "ไม่พบปัญหา"'),
 (@C, 9, N'มีการบันทึกด้วยลายมือที่อ่านออกได้และระบุ ชื่อ นามสกุล วิสัญญีแพทย์/พยาบาลที่รับผิดชอบ', 0, NULL);
INSERT INTO mra.AuditContent (CriteriaSetId, ContentNo, ContentCode, TitleEn, TitleTh, AllowContentNA, AllowDeduction, MaxDeduction, HintText)
INSERT INTO mra.AuditCriterion (ContentId, CriterionNo, CriterionText, AllowNA, NoteText) VALUES
 (@C, 1, N'มีการบันทึกข้อมูลผู้ป่วยถูกต้องครบถ้วน ประกอบด้วย ชื่อ สกุล อายุ HN AN เพศ เป็นต้น', 0, NULL),
 (@C, 2, N'มีบันทึก pre-operative diagnosis และ post-operative diagnosis โดย post-operative diagnosis ไม่ใช้ "same" หรือเครื่องหมายปีกกา หรือ "------"', 0, NULL),
 (@C, 3, N'มีบันทึกชื่อการทำหัตถการถูกต้อง ครบถ้วน สอดคล้องกับวิธีการทำหัตถการนั้น', 0, NULL),
 (@C, 4, N'มีบันทึกรายละเอียดสิ่งที่ตรวจพบจากการผ่าตัดหรือหัตถการ (operative findings) สอดคล้องกับ post-operative diagnosis', 0, NULL),
 (@C, 5, N'มีบันทึกรายละเอียดวิธีการทำหัตถการ (operative procedures) ประกอบด้วย position incision สิ่งที่ตัดออก เป็นต้น รวมถึงการส่งชิ้นเนื้อเพื่อส่งตรวจ', 0, NULL),
 (@C, 6, N'มีบันทึกภาวะแทรกซ้อนที่เกิดขึ้น และจำนวนเลือดที่สูญเสียระหว่างผ่าตัด (ใช้คำว่า minimal blood loss ได้)', 0, N'ไม่มีภาวะดังกล่าวต้องระบุ "ไม่มี"'),
 (@C, 7, N'มีบันทึกวัน เวลา ที่เริ่มต้นและสิ้นสุดการทำหัตถการ', 0, NULL),
 (@C, 8, N'มีบันทึกชื่อ-นามสกุล คณะผู้ร่วมทำหัตถการ ได้แก่ แพทย์ วิสัญญี และ scrub nurse เป็นต้น และวิธีการให้ยาระงับความรู้สึก', 0, NULL),
 (@C, 9, N'มีการบันทึกด้วยลายมือที่อ่านออกได้ และลงลายมือชื่อแพทย์ผู้ทำหัตถการ โดยสามารถระบุได้ว่าเป็นผู้ใด จากชื่อ นามสกุล และเลขที่ใบอนุญาตประกอบวิชาชีพเวชกรรม', 0, NULL);
INSERT INTO mra.AuditContent (CriteriaSetId, ContentNo, ContentCode, TitleEn, TitleTh, AllowContentNA, AllowDeduction, MaxDeduction, HintText)
INSERT INTO mra.AuditCriterion (ContentId, CriterionNo, CriterionText, AllowNA, NoteText) VALUES
 (@C, 1, N'บันทึกการประเมินผู้คลอดแรกรับ: obstetric history (gravida, parity, abortion, live, LMP, EDC, gestational age), ANC history, complication, risk monitoring และการตรวจร่างกายโดยแพทย์หรือพยาบาล', 0, NULL),
 (@C, 2, N'การประเมินผู้คลอดระยะรอคลอด: วันเดือนปี เวลา ชีพจร ความดันโลหิต progress labour (uterine contraction, cervical dilation and effacement membrane), fetal assessment (fetal heart sound, station), complication', 0, NULL),
 (@C, 3, N'มีบันทึกวันที่ ระยะเวลาการคลอดแต่ละ stage', 1, N'กรณี elective caesarean section ให้ระบุ NA'),
 (@C, 4, N'มีบันทึกหัตถการ วิธีการคลอด ข้อบ่งชี้ในการทำสูติศาสตร์หัตถการ ภาวะแทรกซ้อน และการระงับความรู้สึก (ถ้ามี) การทำ episiotomy ตามสภาพผู้คลอด', 0, NULL),
 (@C, 5, N'มีบันทึกคำสั่ง และบันทึกการให้ยาในระยะก่อน ระหว่าง และหลังคลอด', 0, NULL),
 (@C, 6, N'มีบันทึกวันเดือนปี และเวลาที่ทารกคลอด เพศ น้ำหนัก และความยาวของทารก', 0, NULL),
 (@C, 7, N'มีบันทึกการประเมินมารดาระยะหลังคลอด: placenta checked, complication, blood loss, vital signs และสภาพก่อนย้ายออกจากห้องคลอดหรือหลังคลอด 2 ชั่วโมง', 0, NULL),
 (@C, 8, N'มีบันทึกการประเมินทารก Apgar score (1, 5 และ 10 นาที) ประเมินสภาพทารกเบื้องต้น และประเมินภาวะแทรกซ้อน', 0, N'ไม่มีภาวะแทรกซ้อนต้องระบุ "ไม่มี"'),
 (@C, 9, N'มีการบันทึกด้วยลายมือที่อ่านออกได้และลงลายมือชื่อแพทย์ หรือพยาบาลวิชาชีพผู้ทำคลอด โดยสามารถระบุได้ว่าเป็นผู้ใด จากชื่อและนามสกุล', 0, NULL);
INSERT INTO mra.AuditContent (CriteriaSetId, ContentNo, ContentCode, TitleEn, TitleTh, AllowContentNA, AllowDeduction, MaxDeduction, HintText)
INSERT INTO mra.AuditCriterion (ContentId, CriterionNo, CriterionText, AllowNA, NoteText) VALUES
 (@C, 1, N'มีบันทึกการซักประวัติอาการสำคัญ ประวัติปัจจุบัน และประวัติอดีตที่เกี่ยวข้องกับปัญหาที่ต้องการฟื้นฟูสมรรถภาพ', 0, NULL),
 (@C, 2, N'มีบันทึกการตรวจร่างกายในส่วนที่เกี่ยวข้อง สอดคล้องกับปัญหาที่ต้องการฟื้นฟูสมรรถภาพ', 0, NULL),
 (@C, 3, N'มีบันทึกการวินิจฉัยโรคที่สอดคล้อง หรือการวินิจฉัยทางกายภาพบำบัด และมีบันทึกสรุปปัญหาที่ต้องการฟื้นฟูสมรรถภาพ', 0, NULL),
 (@C, 4, N'มีบันทึกเป้าหมายในการฟื้นฟูสมรรถภาพ การวางแผน ชนิดของการบำบัดหรือหัตถการ ข้อห้ามและข้อควรระวัง', 0, NULL),
 (@C, 5, N'มีบันทึกการรักษาที่ให้ในแต่ละครั้ง โดยระบุวันเวลาหรือตำแหน่งที่ทำการบำบัด และระยะเวลาที่ใช้', 0, NULL),
 (@C, 6, N'มีบันทึกการประเมินผลการให้บริการ และความก้าวหน้าของการฟื้นฟูสมรรถภาพตามเป้าหมาย', 0, NULL),
 (@C, 7, N'มีบันทึกสรุปผลการให้บริการฟื้นฟูสมรรถภาพและแผนการจำหน่ายผู้ป่วย', 0, NULL),
 (@C, 8, N'มีบันทึกรายละเอียดการให้ home program หรือคำแนะนำในการปฏิบัติตัว (patient and family education) หรือแผนการดูแลต่อเนื่อง', 0, NULL),
 (@C, 9, N'มีการบันทึกด้วยลายมือที่อ่านออกได้ และลงลายมือชื่อแพทย์เวชศาสตร์ฟื้นฟูพร้อมเลขที่ใบอนุญาต หรือนักกายภาพบำบัดระบุชื่อ สกุล และตำแหน่ง ทุกครั้งที่มีการบำบัด', 0, NULL);
INSERT INTO mra.AuditContent (CriteriaSetId, ContentNo, ContentCode, TitleEn, TitleTh, AllowContentNA, AllowDeduction, MaxDeduction, HintText)
INSERT INTO mra.AuditCriterion (ContentId, CriterionNo, CriterionText, AllowNA, NoteText) VALUES
 (@C, 1, N'การประเมินแรกรับ: มีบันทึกอาการสำคัญ (อาการหลัก 1-2 อาการ ตามด้วยระยะเวลา) และอาการผู้ป่วยแรกรับครอบคลุมตามสภาวะผู้ป่วย และระบุเวลาแรกรับผู้ป่วยไว้ในความดูแล', 0, NULL),
 (@C, 2, N'การระบุปัญหาทางการพยาบาล: ระบุปัญหาการพยาบาลที่สำคัญสอดคล้องกับอาการ อาการแสดงด้านร่างกาย และ/หรือจิตใจ อารมณ์ สังคม จิตวิญญาณ ตั้งแต่แรกรับจนจำหน่าย', 0, NULL),
 (@C, 3, N'กิจกรรมการพยาบาล (Nursing intervention): ครอบคลุมอาการแสดงหรือปัญหาที่สำคัญ มีการประเมินซ้ำตามช่วงเวลาที่เหมาะสม และ/หรือกิจกรรมที่ตอบสนองต่อการตรวจเยี่ยมร่วมกับทีมสุขภาพ (ถ้ามี)', 0, NULL),
 (@C, 4, N'การประเมินการตอบสนองต่อการรักษาพยาบาล: บันทึกการเปลี่ยนแปลงที่ตอบสนองต่อกิจกรรมการพยาบาลหรือการรักษา และบันทึกการตรวจ/การรักษาที่สำคัญ (ถ้ามี) โดยระบุวันเวลา อาการก่อน ขณะ หลังทำ และผลที่ได้', 0, NULL),
 (@C, 5, N'การให้ข้อมูลระหว่างการรักษาพยาบาล: บันทึกการให้ข้อมูลที่จำเป็น การช่วยเหลือด้านร่างกาย และ/หรืออารมณ์จิตใจ และคำแนะนำที่สอดคล้องกับปัญหาและความต้องการของผู้ป่วย/ครอบครัว', 0, NULL),
 (@C, 6, N'การเตรียมความพร้อมเพื่อการดูแลต่อเนื่องที่บ้าน (Discharge plan): บันทึกปัญหาหรือความต้องการหลังจำหน่าย การให้ข้อมูลและการช่วยเหลือให้เกิดการเรียนรู้ดูแลตนเอง และข้อมูลที่สะท้อนความก้าวหน้าในการเรียนรู้/ฝึกทักษะของผู้ป่วย/ครอบครัว', 0, NULL),
 (@C, 7, N'การประสานการดูแลต่อเนื่อง: ระบุปัญหา ความต้องการ ข้อมูลอาการที่ต้องดูแลต่อเนื่องทั้งในโรงพยาบาลและในเครือข่าย/ชุมชน บันทึกการนัดหมายเมื่อมีข้อบ่งชี้ และแนวทางการช่วยเหลือหลังออกจากโรงพยาบาล (ถ้ามี)', 0, NULL),
 (@C, 8, N'การจำหน่ายผู้ป่วย: สรุปอาการ อาการแสดงและสัญญาณชีพ ผลการประเมินความพร้อมก่อนจำหน่าย กิจกรรมการพยาบาลก่อนจำหน่าย เช่น คำแนะนำ การดูแลต่อเนื่อง การนัดตรวจ และข้อมูลส่งต่อ (ถ้ามี)', 0, NULL),
 (@C, 9, N'การบันทึกวันเดือนปี เวลา และการลงลายมือชื่อ: มีวันเวลาแรกรับ ระหว่างการดูแล (ชัดเจนในแต่ละเหตุการณ์และการรายงานแพทย์) และก่อนจำหน่าย ด้วยลายมือที่อ่านออกได้ พร้อมลายมือชื่อและนามสกุลของพยาบาลวิชาชีพผู้บันทึกทุกครั้ง', 0, NULL);
